"""Render docs/results.md from results/*.json. Every number in that file comes from here."""

from __future__ import annotations

import json
from pathlib import Path

R = Path("results")
TAG_ORDER = ["base_zeroshot", "base_fewshot", "qlora", "qlora_gguf"]


def load(name: str) -> dict | None:
    p = R / name
    return json.loads(p.read_text()) if p.exists() else None


def pct(x: float) -> str:
    return f"{100 * x:.1f} %"


def main() -> None:
    out = [
        "# Results",
        "",
        "_Generated by `scripts/make_results_md.py` from `results/*.json`. Do not edit by hand._",
        "",
    ]

    evals = {}
    for p in sorted(R.glob("eval_*.json")):
        d = json.loads(p.read_text())
        if d.get("limit") or d.get("question_source_mode", "final") != "final":
            continue
        evals[(d["tag"], d["split"])] = d
    if evals:
        tags = [t for t in TAG_ORDER if any(k[0] == t for k in evals)] + sorted(
            {k[0] for k in evals} - set(TAG_ORDER)
        )
        out += [
            "## Execution accuracy",
            "",
            "| Model | test_in EX | test_ood EX | test_in valid SQL | test_ood valid SQL |",
            "|---|---|---|---|---|",
        ]
        for t in tags:
            a, b = evals.get((t, "test_in")), evals.get((t, "test_ood"))
            cells = [pct(x["execution_accuracy"]) if x else "TODO(measure)" for x in (a, b)]
            cells += [pct(x["valid_sql_rate"]) if x else "TODO(measure)" for x in (a, b)]
            out.append(f"| {t} | " + " | ".join(cells) + " |")
        out += [
            "",
            "n = 1000 per split; greedy decoding; result-set equality (order-sensitive only with ORDER BY).",
            "",
        ]
        for split in ("test_in", "test_ood"):
            rows = [(t, evals[(t, split)]) for t in tags if (t, split) in evals]
            if not rows:
                continue
            out += [f"### Buckets ({split})", ""]
            dims = ["joins", "aggregation", "group_by", "subquery", "lang", "question_source"]
            header = ["Bucket"] + [t for t, _ in rows]
            out += ["| " + " | ".join(header) + " |", "|" + "---|" * len(header)]
            for dim in dims:
                vals = sorted({v for _, d in rows for v in d["buckets"].get(dim, {})})
                for v in vals:
                    cells = []
                    for _, d in rows:
                        b = d["buckets"].get(dim, {}).get(v)
                        cells.append(f"{pct(b['execution_accuracy'])} (n={b['n']})" if b else "-")
                    out.append(f"| {dim}={v} | " + " | ".join(cells) + " |")
            out += ["", f"### Error taxonomy ({split})", ""]
            classes = list(rows[0][1]["error_taxonomy"])
            out += ["| Class | " + " | ".join(t for t, _ in rows) + " |", "|" + "---|" * (len(rows) + 1)]
            for c in classes:
                out.append(f"| {c} | " + " | ".join(str(d["error_taxonomy"][c]) for _, d in rows) + " |")
            out.append("")

    ds = load("dataset_build.json")
    if ds:
        out += [
            "## Dataset (execution-verified)",
            "",
            "| Split | n | DE / EN | renamed schema share | dropped duplicates |",
            "|---|---|---|---|---|",
        ]
        for s, d in ds["splits"].items():
            out.append(
                f"| {s} | {d['n']} | {d['by_lang'].get('de', 0)} / {d['by_lang'].get('en', 0)} | "
                f"{d['renamed_share']} | {d['duplicates_dropped']} |"
            )
        out += ["", f"Leak check: {ds.get('leak_check', 'n/a')}.", ""]
    para = load("paraphrase.json")
    if para:
        out += [
            f"## Paraphrases ({para['model']})",
            "",
            "| Split | accepted paraphrase share | outcomes |",
            "|---|---|---|",
        ]
        for s, d in para["splits"].items():
            out.append(f"| {s} | {pct(d['paraphrase_share'])} | {d['outcomes']} |")
        out.append("")
    bench = load("bench_sqlnorm.json")
    if bench:
        out += [
            "## Rust sqlnorm vs sqlglot",
            "",
            f"{bench['n_queries']} queries, parse + canonicalise + hash, median of {bench['repeats']} runs:",
            "",
            "| Implementation | queries/s |",
            "|---|---|",
        ]
        for k, v in bench["queries_per_second"].items():
            out.append(f"| {k} | {v:,} |")
        out += [
            "",
            f"Speedup: {bench['speedup_vs_sqlglot']['per_call']}x per call "
            f"(sqlglot {bench['env']['sqlglot']}, Rust tokenizer: {bench['env']['sqlglot_rust_tokenizer']}).",
            "",
        ]
    tr = load("train_qlora.json")
    if tr:
        out += [
            "## QLoRA training run",
            "",
            f"{tr['base_model']}, {tr['train_samples']} samples, {tr['epochs']} epoch ({tr['steps']} steps), "
            f"LoRA r={tr['lora']['r']} alpha={tr['lora']['alpha']}: {tr['train_seconds'] / 3600:.2f} h "
            f"on one 16 GB GPU, peak VRAM {tr['peak_vram_allocated_gib']} GiB, "
            f"{tr['seconds_per_step']} s/step.",
            "",
            "| step | eval loss |",
            "|---|---|",
        ]
        seen = set()
        for step, loss in tr["eval_loss_curve"]:
            if step not in seen:
                seen.add(step)
                out.append(f"| {step} | {loss} |")
        out.append("")
    smoke = [load(f) for f in ("smoke_7b_short.json", "smoke_7b_seq1024.json")]
    if any(smoke):
        out += ["## QLoRA smoke test", "", "| tokens/sample | peak VRAM (GiB) | s/step |", "|---|---|---|"]
        for d in smoke:
            if d:
                out.append(
                    f"| {d['sample_tokens_mean']} | {d['peak_vram_allocated_gib']} "
                    f"| {d['seconds_per_step']} |"
                )
        out.append("")
    Path("docs/results.md").write_text("\n".join(out))
    print("wrote docs/results.md")
    update_readme(evals)


def update_readme(evals: dict) -> None:
    """Headline tables between the README markers."""
    lines = []
    if evals:
        lines += [
            "| Model (Qwen2.5-Coder-7B, 4-bit) | test_in EX | test_ood EX (unseen schema) |",
            "|---|---|---|",
        ]
        names = {
            "base_zeroshot": "base, zero-shot",
            "base_fewshot": "base, 3-shot",
            "qlora": "QLoRA (ours), NF4 + adapter",
            "qlora_gguf": "QLoRA merged, GGUF Q4_K_M (served by Ollama)",
        }
        for t in [t for t in TAG_ORDER if any(k[0] == t for k in evals)]:
            a, b = evals.get((t, "test_in")), evals.get((t, "test_ood"))
            fmt = [pct(x["execution_accuracy"]) if x else "TODO(measure)" for x in (a, b)]
            lines.append(f"| {names.get(t, t)} | {fmt[0]} | {fmt[1]} |")
        lines += [
            "",
            "n = 1000 questions per split (about half German), greedy decoding, execution accuracy = "
            "result-set equality.",
            "",
        ]
    lt = load("loadtest.json")
    if lt:
        a, b = lt["runs"].get("no_cache"), lt["runs"].get("with_cache")
        if a and b:
            lines += [
                "| Serving (vegeta, same request stream) | p50 | p95 | cache hit rate |",
                "|---|---|---|---|",
                f"| without Redis cache | {a['latency_ms']['50th']} ms | {a['latency_ms']['95th']} ms | - |",
                f"| with Redis cache | {b['latency_ms']['50th']} ms | {b['latency_ms']['95th']} ms | "
                f"{pct(b['hit_rate'])} |",
                "",
                f"{lt['requests_per_run']} requests per run at {a['rate_per_s']}/s: "
                f"{lt['distinct_questions']} distinct "
                f"test_ood questions x {lt['repeat']}, 30 % of repeats as case/whitespace variants "
                f"(max possible hit rate {pct(lt['max_possible_hit_rate'])}); "
                "gateway -> executor -> GGUF on one GPU.",
                "",
            ]
    tr = load("train_qlora.json")
    if tr:
        lines += [
            f"Training: {tr['train_samples']} samples, {tr['epochs']:.0f} epoch, "
            f"{tr['train_seconds'] / 3600:.1f} h on an RTX 5060 Ti 16 GB, "
            f"peak VRAM {tr['peak_vram_allocated_gib']} GiB.",
            "",
        ]
    bench = load("bench_sqlnorm.json")
    if bench:
        lines += [
            f"Rust `sqlnorm` (parse + canonicalise + hash): **{bench['speedup_vs_sqlglot']['per_call']}x** "
            f"faster than sqlglot on {bench['n_queries']:,} queries.",
            "",
        ]
    ds = load("dataset_build.json")
    if ds:
        n = {s: d["n"] for s, d in ds["splits"].items()}
        lines += [
            f"Dataset: {n.get('train')} train / {n.get('val')} val / {n.get('test_in')} test_in / "
            f"{n.get('test_ood')} test_ood, all execution-verified.",
            "",
        ]
    readme = Path("README.md")
    txt = readme.read_text()
    start, end = "<!-- results:start -->", "<!-- results:end -->"
    i, j = txt.index(start) + len(start), txt.index(end)
    readme.write_text(txt[:i] + "\n" + "\n".join(lines) + "\n" + txt[j:])
    print("updated README.md results section")


if __name__ == "__main__":
    main()
